ALTER TABLE "catalog_versions" ADD CONSTRAINT "catalog_real_evidence" CHECK (coalesce("catalog_versions"."body"->'synthetic' = 'false'::jsonb AND jsonb_typeof("catalog_versions"."body"->'profiles') = 'array' AND jsonb_typeof("catalog_versions"."body"->'sources') = 'array' AND jsonb_array_length("catalog_versions"."body"->'profiles') between 1 and 300 AND jsonb_array_length("catalog_versions"."body"->'sources') between 1 and 600 AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.profiles[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'profiles') AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.sources[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'sources') AND ("catalog_versions"."schema_version" = '1' OR (jsonb_typeof("catalog_versions"."body"->'issues') = 'array' AND jsonb_array_length(jsonb_path_query_array("catalog_versions"."body", '$.issues[*] ? (@.synthetic == false)')) = jsonb_array_length("catalog_versions"."body"->'issues'))),false));